<template>
  <div class="manager-page"><div class="page-heading"><div><div class="eyebrow">TEACHING</div><h1>作业管理</h1><p>发布学习任务，设置截止时间并跟踪提交情况。</p></div><el-button type="primary" round @click="handleAdd"><el-icon><Plus /></el-icon>布置作业</el-button></div><div class="card table-card"><div class="toolbar"><el-input v-model="query.title" clearable placeholder="搜索作业标题" style="width:280px" @keyup.enter="search"><template #prefix><el-icon><Search /></el-icon></template></el-input><div class="grow"></div><span class="text-muted">共 {{total}} 项作业</span></div><el-table :data="rows" stripe><el-table-column label="作业" min-width="300"><template #default="{row}"><div class="task-cell"><div class="num">0{{row.id}}</div><div><b>{{row.title}}</b><span>{{row.content}}</span></div></div></template></el-table-column><el-table-column prop="teacherName" label="发布教师" width="110"/><el-table-column label="截止时间" width="150"><template #default="{row}">{{date(row.deadline)}}</template></el-table-column><el-table-column label="提交数" width="90"><template #default="{row}"><el-tag effect="plain">{{row.submitCount||0}} 人</el-tag></template></el-table-column><el-table-column label="操作" width="200" align="center"><template #default="{row}"><el-button text type="primary" @click="router.push('/manager/submit')">批改</el-button><el-button text type="primary" @click="handleEdit(row)">编辑</el-button><el-button text type="danger" @click="del(row.id)">删除</el-button></template></el-table-column></el-table><div class="pagination-wrap"><el-pagination background layout="prev,pager,next" :total="total" :page-size="query.pageSize" v-model:current-page="query.pageNum" @current-change="load"/></div></div>
<el-dialog v-model="visible" :title="form.id?'编辑作业':'布置作业'" width="650px"><el-form :model="form" label-position="top"><el-form-item label="作业标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="作业说明"><el-input v-model="form.content" type="textarea" :rows="6"/></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="附件"><el-upload :action="uploadUrl" :on-success="r=>{if(r.code==='200')form.file=r.data}"><el-button>上传附件</el-button></el-upload></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div>
</template>
<script setup>
import {reactive,ref,computed,onMounted} from 'vue';import {useRouter} from 'vue-router';import request from '@/utils/request';import {ElMessage,ElMessageBox} from 'element-plus'
const router=useRouter();const user=JSON.parse(localStorage.getItem('system-user')||'{}');const uploadUrl=import.meta.env.VITE_BASE_URL+'/files/upload';const query=reactive({title:'',pageNum:1,pageSize:8});const data=reactive({rows:[],total:0});const rows=computed(()=>data.rows),total=computed(()=>data.total),visible=ref(false),form=reactive({});const date=v=>v?String(v).replace('T',' ').slice(0,16):'长期';const load=()=>request.get('/homework/selectPage',{params:query}).then(res=>{if(res.code==='200'){data.rows=res.data.list||[];data.total=res.data.total||0}});const search=()=>{query.pageNum=1;load()};const handleAdd=()=>{Object.assign(form,{id:null,title:'',content:'',file:'',teacherId:user.id,deadline:null});visible.value=true};const handleEdit=row=>{Object.assign(form,row);visible.value=true};const save=()=>request[form.id?'put':'post'](form.id?'/homework/update':'/homework/add',form).then(res=>{if(res.code==='200'){ElMessage.success('保存成功');visible.value=false;load()}else ElMessage.error(res.msg)});const del=id=>ElMessageBox.confirm('确认删除该作业？','提示').then(()=>request.delete('/homework/delete/'+id).then(()=>{ElMessage.success('已删除');load()}));onMounted(load)
</script>
<style scoped>.task-cell{display:flex;gap:14px;align-items:center}.task-cell .num{font-family:var(--font-serif);color:var(--gold);font-size:20px}.task-cell div:last-child{display:flex;flex-direction:column;gap:5px;min-width:0}.task-cell span{color:var(--muted);font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:370px}</style>

